+const winterReady = [
+  { category: "top", colors: ["cream"], formality: 3, style_tags: [], seasons: ["Winter"] },
+  { category: "bottom", colors: ["navy"], formality: 3, style_tags: [], seasons: ["Winter"] },
+  { category: "shoes", colors: ["brown"], formality: 3, style_tags: [], seasons: ["Winter"] },
+];
+const summerOnly = [
