1	import { colorHarmonyScore, leanScore } from "./color";
2	import { seasonFit } from "./season";
3	
4	export type ScoreItem = {
5	  category: string;
6	  colors: string[];
7	  formality: number | null;
8	  style_tags?: string[];
9	  seasons?: string[];
10	};
11	export type Ctx = {
12	  aesthetic: string[];
13	  band: [number, number];
14	  /** Refine "Lean into" colour families. Empty = no preference. */
15	  lean?: string[];
16	  /**
17	   * Item ids from the set a regenerate is replacing. A SOFT preference applied
18	   * in `rankTopN`, never a filter: pieces sink in the ranking but are never
19	   * removed from the closet, so a small wardrobe still returns its one good
20	   * outfit instead of an empty screen.
21	   */
22	  recentlyShown?: string[];
23	  /** The current season ("Winter"). Absent = no season preference at all. */
24	  season?: string;
25	};
26	
27	/**
28	 * How much of the score the colour lean is allowed to claim when one is asked
29	 * for. High enough to reorder the top 20 decisively, low enough that a combo
30	 * missing the colour still beats an incoherent one that has it — the lean is a
31	 * preference, never an eliminator.
32	 */
33	const LEAN_WEIGHT = 0.3;
34	
35	/**
36	 * The same bargain for season. Slightly lower than the lean because a lean is an
37	 * explicit request the user just made, while season is inferred from the month.
38	 * Both together cap at 0.5, so coherence and colour harmony always keep half the
39	 * score — an off-season combo that actually works still beats an in-season mess.
40	 */
41	const SEASON_WEIGHT = 0.2;
42	
43	/** 1.0 = identical formality; falls off with spread. */
44	export function formalityCoherence(formalities: number[]): number {
45	  const f = formalities.filter((x) => typeof x === "number");
46	  if (f.length < 2) return 1;
47	  const spread = Math.max(...f) - Math.min(...f);
48	  return Math.max(0, 1 - spread / 4); // spread of 4 (1↔5) → 0
49	}
50	
51	export function scoreCombo(items: ScoreItem[], ctx: Ctx): number {
52	  const colors = items.flatMap((i) => i.colors);
53	  const harmony = colorHarmonyScore(colors);
54	  const coherence = formalityCoherence(items.map((i) => i.formality ?? 3));
55	  const dnaHits = items.filter((i) => i.style_tags?.some((t) => ctx.aesthetic.includes(t))).length;
56	  const dna = items.length ? dnaHits / items.length : 0;
57	  const base = 0.45 * harmony + 0.35 * coherence + 0.2 * dna;
58	
59	  // Each preference claims its weight only when it applies, so with neither one
60	  // set the score is byte-identical to what it was before either landed.
61	  const wl = ctx.lean?.length ? LEAN_WEIGHT : 0;
62	  const ws = ctx.season ? SEASON_WEIGHT : 0;
63	  return Math.min(
64	    1,
65	    base * (1 - wl - ws) + wl * leanScore(colors, ctx.lean ?? []) + ws * seasonFit(items, ctx.season),
66	  );
67	}
