1	/**
2	 * Season is a PREFERENCE, not an eligibility gate.
3	 *
4	 * A hard season filter ran against every REQUIRED slot, so one narrowly-tagged
5	 * category could zero the entire result. Measured on a constructed closet — 10
6	 * tops, 4 bottoms, 4 shoes, every piece wearable, the trousers simply lacking a
7	 * Winter tag — the same wardrobe produced 40 combos in summer and 0 in winter,
8	 * with `missingCategory` blaming Bottoms. Outerwear and the Refine colour lean
9	 * both moved to the soft-preference model for exactly this reason; season now
10	 * follows them — it orders candidates and weights the score, and can never
11	 * eliminate one.
12	 *
13	 * The MEASURED signal still filters hard (`weatherRules`: rain excludes suede,
14	 * cold adds a layer). That is a real reading of the day. A season tag is a
15	 * coarse label derived from the calendar month, which is a much blunter
16	 * instrument and does not deserve veto power.
17	 */
18	
19	/**
20	 * Does this item suit the season?
21	 *
22	 * Case-insensitive on purpose: the DB and the AI tagger store Title case
23	 * ("Winter", `lib/ai/tagging-schema.ts`) while the generator's test fixtures use
24	 * lower case. An untagged item counts as in-season — absence of tags is absence
25	 * of an opinion, not a reason to rank it last.
26	 */
27	export function inSeason(seasons: string[] | undefined, season: string | undefined): boolean {
28	  if (!season) return true;
29	  if (!seasons || seasons.length === 0) return true;
30	  const s = season.toLowerCase();
31	  return seasons.some((x) => x.toLowerCase() === s);
32	}
33	
34	/** The fraction of a combo's pieces that suit the season. 1 = all of them. */
35	export function seasonFit(items: { seasons?: string[] }[], season: string | undefined): number {
36	  if (!items.length) return 1;
37	  return items.filter((i) => inSeason(i.seasons, season)).length / items.length;
38	}
39	
40	/** Title case to match the DB tag vocabulary. */
41	export function currentSeason(d: Date): string {
42	  const m = d.getMonth();
43	  return m < 2 || m === 11 ? "Winter" : m < 5 ? "Spring" : m < 8 ? "Summer" : "Autumn";
44	}
